(window.webpackJsonp=window.webpackJsonp||[]).push([[30],{384:function(t,e){"use strict";e.__esModule=!0,e.default={render:function(){return this.$createElement("div",{staticClass:"theme-default-content content__default lab-wide",domProps:{innerHTML:"\n<div class=\"lab-content join-page\">\r\n<h1 id=\"加入-mi2\"><a href=\"#加入-mi2\" class=\"header-anchor\">#</a> 加入 MI² Lab</h1>\r\n<section class=\"join-hero\"><p class=\"eyebrow\">研究生培养 · 科研训练 · 医工合作</p><h2>面向临床真实问题，构建医学智能</h2><p>我们欢迎希望把严谨计算方法与真实医学问题结合起来的同学。课题组兼顾基础算法、多模态医学数据和医院临床合作，推动研究成果走向可验证的医学价值。</p><div class=\"profile-actions\"><a class=\"button-secondary\" href=\"#申请流程\">查看申请流程</a></div></section>\n\n<h2 id=\"为什么选择-mi2\"><a href=\"#为什么选择-mi2\" class=\"header-anchor\">#</a> 为什么选择 MI² Lab</h2>\n<div class=\"value-grid\"><article><strong>国际化研究视野</strong><p>在 TU/e、美国南加州大学凯克医学院、中国科学院和南京大学积累的跨机构科研经验。</p></article><article><strong>高水平科研训练</strong><p>研究成果发表于 TPAMI、TMI、Medical Image Analysis、JBHI、Pattern Recognition、MICCAI 等重要期刊与会议。</p></article><article><strong>紧密临床连接</strong><p>围绕医学影像和临床数据开展合作，将算法转化为可量化的影像标志物和诊疗支持工具。</p></article></div>\n\r\n<h2 id=\"希望你是\"><a href=\"#希望你是\" class=\"header-anchor\">#</a> 希望你是</h2>\r\n<div class=\"candidate-layout\"><ul class=\"check-list\"><li>计划申请南京大学硕士、普通博士或直博项目。</li><li>具有计算机、生物医学工程、医学影像、临床医学、应用数学或相关专业背景。</li><li>对医学影像、计算机视觉、多模态大模型、医学智能体或医工交叉研究有明确兴趣。</li><li>具备良好的编程与数学基础；有论文成果或开源项目经验者优先。</li><li>做事踏实、重视合作，遇到问题主动沟通，愿意长期投入科研。</li></ul><aside><p class=\"eyebrow\">同样欢迎</p><p>科研助理、实习生、访问学生，以及来自医院、影像中心和生命科学团队的合作者。</p></aside></div>\n\r\n<h2 id=\"招生信息\"><a href=\"#招生信息\" class=\"header-anchor\">#</a> 招生信息</h2>\r\n<div class=\"info-table\"><div><span>所在单位</span><strong>南京大学（苏州校区）生物医学工程学院</strong></div><div><span>招生导师</span><strong>张炯教授</strong></div><div><span>招生类型</span><strong>硕士 · 普通博士 · 直博</strong></div><div><span>招生名额</span><strong>以南京大学及学院当年招生计划为准</strong></div></div>\n\r\n<h2 id=\"申请流程\"><a href=\"#申请流程\" class=\"header-anchor\">#</a> 申请流程</h2>\r\n<div class=\"steps\"><div><span>1</span><h3>判断方向匹配</h3><p>阅读课题组近期论文和项目成果，明确自己感兴趣的具体医学问题或技术方向。</p></div><div><span>2</span><h3>准备申请材料</h3><p>准备简短自我介绍、个人简历、成绩单和研究兴趣；如有论文、代码或项目，请附相关链接。</p></div><div><span>3</span><h3>联系课题组</h3><p>发送邮件至 <a href=\"mailto:lixiang.cog@smail.nju.edu.cn\">lixiang.cog@smail.nju.edu.cn</a>。正式申请按南京大学及学院最新通知执行。</p></div></div>\n<div class=\"team-callout application-callout\"><div><p class=\"eyebrow\">开始交流</p><h3>告诉我们，你希望解决什么医学问题。</h3><p>具体名额和时间安排以学校当年度招生计划为准。</p></div><a class=\"button-primary\" href=\"mailto:lixiang.cog@smail.nju.edu.cn\">联系导师</a></div>\n</div>"}})}}}}]);
